/**
 * Deterministic randomness for SaaSBench.
 *
 * A benchmark corpus that cannot be regenerated byte for byte is not a benchmark, it is a fixture
 * nobody can audit. Everything downstream — documents, queries, qrels, ACLs, splits — draws from a
 * seeded stream, so `generate.ts --seed 42` produces the same corpus on any machine, and the
 * manifest's content hash is a real check rather than a record of one particular afternoon.
 *
 * mulberry32: 32-bit state, well-distributed, and short enough to read. Cryptographic quality is
 * irrelevant here; reproducibility is the whole requirement.
 */
export class Rng {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  /** Uniform in [0, 1). */
  next(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /** Uniform integer in [min, max]. */
  int(min: number, max: number): number {
    return min + Math.floor(this.next() * (max - min + 1));
  }

  /** One element, uniformly. */
  pick<T>(xs: readonly T[]): T {
    if (xs.length === 0) throw new Error("[saasbench] pick() from an empty array");
    return xs[Math.floor(this.next() * xs.length)];
  }

  /** `n` distinct elements, or all of them if `n` exceeds the supply. */
  sample<T>(xs: readonly T[], n: number): T[] {
    return this.shuffle(xs).slice(0, Math.min(n, xs.length));
  }

  /** Fisher-Yates, on a copy. */
  shuffle<T>(xs: readonly T[]): T[] {
    const out = [...xs];
    for (let i = out.length - 1; i > 0; i--) {
      const j = Math.floor(this.next() * (i + 1));
      [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
  }

  /** True with probability `p`. */
  chance(p: number): boolean {
    return this.next() < p;
  }

  /** A fresh stream, derived deterministically — so one subsystem's draws cannot shift another's. */
  fork(label: string): Rng {
    let h = 2166136261 >>> 0;
    for (let i = 0; i < label.length; i++) {
      h ^= label.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return new Rng((this.state ^ h) >>> 0);
  }
}

/** Stable content hash, for the manifest. */
export async function sha256(text: string): Promise<string> {
  const { createHash } = await import("node:crypto");
  return createHash("sha256").update(text, "utf8").digest("hex");
}
